export function LocalSearch({
  label = "{{label}}",
  placeholder = "{{placeholder}}",
  scope = "{{scope}}",
  accent = "{{accent}}",
}) {
  const scopeLabel = { page: "this page", list: "this list", folder: "this folder" }[scope] ?? scope;
  return (
    <form role="search" style={{ display: "block", fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", maxWidth: 260 }}>
      <label htmlFor="lsearch-input" style={{ display: "block", marginBottom: 4, fontWeight: 500 }}>{label}</label>
      <div style={{
        display: "flex", alignItems: "center", gap: 6, boxSizing: "border-box", padding: "6px 10px",
        background: "#FAF7F2", border: `1.5px solid ${accent}66`, borderRadius: 7,
      }}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true" style={{ flex: "none", color: "#24143080" }}>
          <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
          <path d="M20 20l-3.5-3.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
        </svg>
        <input id="lsearch-input" type="search" placeholder={placeholder} style={{ flex: 1, minWidth: 0, border: "none", background: "transparent", font: "inherit", color: "#241430", outline: "none" }} />
      </div>
      <p style={{ margin: "6px 0 0", fontSize: 11.5, color: "#24143090" }}>Searching within: <b>{scopeLabel}</b></p>
    </form>
  );
}
